package com.oms.order.service;
import com.oms.common.tenant.TenantRouting;
import com.oms.common.task.ScopedWorkExecutor;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.annotation.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.ExchangeService.map;
/** Durable shop cursors and fixed windows. Immediate work and Quartz share the same leased path. */
@Service public class ExchangeSync {
    @Resource private OrderRepository repository;
    @Resource private ExchangeService exchanges;
    @Resource private PlatformExchangeService platformExchanges;
    @Resource private TenantRouting tenants;
    @Resource private ExchangeExecution execution;
    private final ScopedWorkExecutor executor=new ScopedWorkExecutor("exchange");
    private final Set<String> active=ConcurrentHashMap.newKeySet();
    private final Set<String> requested=ConcurrentHashMap.newKeySet();
    private TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    public Map<String,Object> poll(){int queued=0;for(String company:tenants.companies())try(TenantRouting.Binding ignored=tenants.open(company)){if(kick(company))queued++;}return map("queued_companies",queued);}
    public boolean kick(String company){TenantRouting.Route scope=tenants.captureForContinuation(company);String key=scope.datasource()+"/"+company;requested.add(key);if(!active.add(key))return false;boolean submitted=executor.submit(scope,()->{requested.remove(key);try{run(company);}finally{active.remove(key);if(requested.remove(key))kick(company);}});if(!submitted){active.remove(key);requested.remove(key);}return submitted;}
    public Map<String,Object> submit(String company,Map<String,Object> input,String actor){long channel=number(input,"channel_id");Map<String,Object> cap=exchanges.capability(company,channel);require(number(cap,"read_enabled")==1&&Boolean.TRUE.equals(cap.get("can_query")),"店铺换货查询未就绪");String request=text(input,"request_key");require(request.matches("[A-Za-z0-9_-]{8,64}"),"请求标识无效，请刷新重试");String ids=text(input,"dispute_ids").trim();LocalDateTime end=LocalDateTime.now().withNano(0),start=end.minusDays(1);List<String> selected=new ArrayList<>();String mode="MANUAL";
        if(!ids.isEmpty()){mode="IDS";for(String id:ids.split("[\\s,，;；]+")){require(id.matches("[1-9][0-9]{0,63}"),"平台换货单号格式无效");if(!selected.contains(id))selected.add(id);}require(!selected.isEmpty()&&selected.size()<=20,"每次最多补全20个换货申请");}
        else{start=time(text(input,"start_time"));end=time(text(input,"end_time"));require(start.isBefore(end)&&!end.isAfter(LocalDateTime.now().plusMinutes(1))&&Duration.between(start,end).compareTo(Duration.ofDays(31))<=0,"请选择开始不晚于结束、最多31天的同步范围");}
        final LocalDateTime a=start,b=end;final String type=mode;long id=tx().execute(s->{repository.db().update("INSERT IGNORE INTO oms_exchange_config(company_code,channel_id,initial_time,cursor_time,updated_by) VALUES (?,?,?,?,?)",company,channel,a.format(TIME),a.format(TIME),actor);repository.db().query("SELECT channel_id FROM oms_exchange_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,company,channel);List<Map<String,Object>> existing=repository.db().query("SELECT * FROM oms_exchange_sync WHERE company_code=? AND channel_id=? AND request_key=?",ROW,company,channel,request);if(!existing.isEmpty()){Map<String,Object> old=existing.get(0);require(type.equals(text(old,"mode"))&&(type.equals("IDS")?strings(old.get("dispute_ids")).equals(selected):a.format(TIME).equals(text(old,"start_time"))&&b.format(TIME).equals(text(old,"end_time"))),"请求标识已用于其他同步范围");return number(old,"id");}repository.db().update("INSERT INTO oms_exchange_sync(company_code,channel_id,mode,start_time,end_time,dispute_ids,actor,request_key) VALUES (?,?,?,?,?,?,?,?)",company,channel,type,a.format(TIME),b.format(TIME),encode(selected),actor,request);return repository.db().queryForObject("SELECT id FROM oms_exchange_sync WHERE company_code=? AND channel_id=? AND request_key=?",Long.class,company,channel,request);});return map("id",id,"state","PENDING");}
    public List<Map<String,Object>> tasks(String company){return repository.db().query("SELECT id,channel_id,mode,start_time,end_time,page_no,state,attempts,synced_count,new_count,updated_count,unchanged_count,failed_count,last_error,create_time FROM oms_exchange_sync WHERE company_code=? ORDER BY id DESC LIMIT 50",ROW,company);}
    public Map<String,Object> task(String company,long id){List<Map<String,Object>> rows=repository.db().query("SELECT id,channel_id,mode,start_time,end_time,page_no,state,attempts,synced_count,new_count,updated_count,unchanged_count,failed_count,last_error,actor,create_time FROM oms_exchange_sync WHERE company_code=? AND id=?",ROW,company,id);require(rows.size()==1,"换货同步任务不存在或无权访问");Map<String,Object> t=rows.get(0);t.put("items",repository.db().query("SELECT i.dispute_id,i.result,i.message,i.platform_exchange_id,COALESCE(p.business_exchange_id,i.exchange_id) exchange_id,e.exchange_sn,e.state business_state FROM oms_exchange_sync_item i LEFT JOIN oms_platform_exchange p ON p.company_code=i.company_code AND p.id=i.platform_exchange_id LEFT JOIN oms_exchange e ON e.company_code=i.company_code AND e.id=COALESCE(p.business_exchange_id,i.exchange_id) WHERE i.company_code=? AND i.task_id=? ORDER BY i.id DESC LIMIT 100",ROW,company,id));t.put("item_count",repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_sync_item WHERE company_code=? AND task_id=?",Long.class,company,id));return t;}
    public void retry(String company,long id){require(repository.db().update("UPDATE oms_exchange_sync SET state='RETRY',attempts=0,next_attempt=NOW() WHERE company_code=? AND id=? AND state IN ('FAILED','RETRY')",company,id)==1,"当前换货同步任务无需重试");}
    private void fence(String company,long channel,String lease){require(!repository.db().query("SELECT channel_id FROM oms_exchange_config WHERE company_code=? AND channel_id=? AND lease_token=? AND lease_until>NOW() FOR UPDATE",ROW,company,channel,lease).isEmpty(),"换货同步租约已失效");}
    private void processItem(String company,long channel,String lease,Map<String,Object> task,String dispute){require(dispute.matches("[1-9][0-9]{0,63}"),"平台换货单号无效");long id=number(task,"id");List<String> old=repository.db().queryForList("SELECT result FROM oms_exchange_sync_item WHERE company_code=? AND task_id=? AND dispute_id=?",String.class,company,id,dispute);if(!old.isEmpty()&&Arrays.asList("NEW","UPDATED","DUPLICATE","OLDER","INVALID","CONFLICT").contains(old.get(0)))return;renew(company,channel,lease);
        try{Map<String,Object> response=exchanges.call(company,channel,"DETAIL",map("dispute_id",dispute,"fields",ExchangeService.FIELDS));Map<String,Object> payload=ExchangeService.object(response.get("exchange"));tx().execute(t->{fence(company,channel,lease);Map<String,Object> outcome=platformExchanges.ingest(company,channel,payload,text(task,"actor"));repository.db().update("INSERT INTO oms_exchange_sync_item(company_code,task_id,dispute_id,platform_exchange_id,exchange_id,result,message) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE platform_exchange_id=VALUES(platform_exchange_id),exchange_id=VALUES(exchange_id),result=VALUES(result),message=VALUES(message)",company,id,dispute,outcome.get("id"),outcome.get("business_exchange_id"),outcome.get("outcome"),"CONFLICT".equals(outcome.get("outcome"))?"同版本内容冲突，请核对平台来源":"INVALID".equals(outcome.get("outcome"))?"平台资料异常，已保留来源，请到平台换货核对":"平台申请已保存；未自动同意或操作库存");return null;});}
        catch(RuntimeException e){String message=e instanceof IllegalArgumentException||e instanceof ExchangeService.PlatformFailure?e.getMessage():"换货申请读取失败，请查看平台交互日志";if(message==null)message="换货同步失败";final String error=message.substring(0,Math.min(500,message.length()));tx().execute(t->{fence(company,channel,lease);repository.db().update("INSERT INTO oms_exchange_sync_item(company_code,task_id,dispute_id,result,message) VALUES (?,?,?,'FAILED',?) ON DUPLICATE KEY UPDATE result='FAILED',message=VALUES(message)",company,id,dispute,error);return null;});}}
    private long counts(String company,long channel,String lease,long task){return tx().execute(t->{fence(company,channel,lease);Map<String,Object> c=repository.db().query("SELECT COUNT(*) n,COALESCE(SUM(result='NEW'),0) fresh,COALESCE(SUM(result='UPDATED'),0) changed,COALESCE(SUM(result IN ('DUPLICATE','OLDER')),0) same,COALESCE(SUM(result IN ('FAILED','CONFLICT','INVALID')),0) failed FROM oms_exchange_sync_item WHERE company_code=? AND task_id=?",ROW,company,task).get(0);repository.db().update("UPDATE oms_exchange_sync SET synced_count=?,new_count=?,updated_count=?,unchanged_count=?,failed_count=? WHERE company_code=? AND id=?",c.get("n"),c.get("fresh"),c.get("changed"),c.get("same"),c.get("failed"),company,task);return number(c,"failed");});}
    void run(String company){for(Map<String,Object> config:repository.db().query("SELECT channel_id FROM oms_exchange_config WHERE company_code=? AND ((enabled=1 AND next_run<=NOW()) OR EXISTS(SELECT 1 FROM oms_exchange_sync s WHERE s.company_code=oms_exchange_config.company_code AND s.channel_id=oms_exchange_config.channel_id AND s.state IN ('PENDING','RUNNING','RETRY') AND s.next_attempt<=NOW())) ORDER BY next_run,channel_id LIMIT 10",ROW,company))shop(company,number(config,"channel_id"));platformExchanges.autoConvert(company);execution.pollCompany(company);}
    private void renew(String company,long channel,String lease){require(repository.db().update("UPDATE oms_exchange_config SET lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE company_code=? AND channel_id=? AND lease_token=? AND lease_until>NOW()",company,channel,lease)==1,"换货同步租约已失效");}
    @SuppressWarnings("unchecked") void shop(String company,long channel){String lease=UUID.randomUUID().toString().replace("-","");if(repository.db().update("UPDATE oms_exchange_config SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 180 SECOND) WHERE company_code=? AND channel_id=? AND (lease_until IS NULL OR lease_until<NOW())",lease,company,channel)!=1)return;Long taskId=null;
        try{
            Map<String,Object> task=tx().execute(s->{Map<String,Object> c=repository.db().query("SELECT * FROM oms_exchange_config WHERE company_code=? AND channel_id=? FOR UPDATE",ROW,company,channel).get(0);List<Map<String,Object>> pending=repository.db().query("SELECT * FROM oms_exchange_sync WHERE company_code=? AND channel_id=? AND state IN ('PENDING','RUNNING','RETRY') AND next_attempt<=NOW() ORDER BY id LIMIT 1 FOR UPDATE",ROW,company,channel);
                if(pending.isEmpty()&&repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_sync WHERE company_code=? AND channel_id=? AND mode='AUTO' AND state='FAILED' AND end_time>?",Long.class,company,channel,c.get("cursor_time"))==0&&number(c,"enabled")==1&&c.get("next_run")!=null&&!time(text(c,"next_run")).isAfter(LocalDateTime.now())){LocalDateTime start=time(text(c,"cursor_time")).minusMinutes(2),initial=time(text(c,"initial_time")),end=LocalDateTime.now().minusSeconds(3).withNano(0);if(start.isBefore(initial))start=initial;if(end.isAfter(start.plusDays(1)))end=start.plusDays(1);if(end.isAfter(start)){long id=repository.insert("INSERT INTO oms_exchange_sync(company_code,channel_id,mode,start_time,end_time,actor,request_key) VALUES (?,?,'AUTO',?,?,'定时任务',?)",company,channel,start.format(TIME),end.format(TIME),UUID.randomUUID().toString());pending=repository.db().query("SELECT * FROM oms_exchange_sync WHERE company_code=? AND id=?",ROW,company,id);}}
                if(pending.isEmpty())return null;Map<String,Object> found=pending.get(0);repository.db().update("UPDATE oms_exchange_sync SET state='RUNNING' WHERE company_code=? AND id=?",company,found.get("id"));return found;});if(task==null)return;taskId=number(task,"id");boolean done;
            if("IDS".equals(text(task,"mode"))){for(String dispute:strings(task.get("dispute_ids")))processItem(company,channel,lease,task,dispute);done=true;}
            else{Map<String,Object> args=map("fields",ExchangeService.FIELDS.replace(",refund_phase","").replace(",operation_contraint",""),"page_no",task.get("page_no"),"page_size",30,"start_gmt_modified_time",task.get("start_time"),"end_gmt_modifed_time",task.get("end_time"));Map<String,Object> page=exchanges.call(company,channel,"LIST",args);List<Map<String,Object>> rows=(List<Map<String,Object>>)page.get("records");require(rows!=null&&rows.size()<=30,"平台换货列表响应异常");for(Map<String,Object> row:rows)processItem(company,channel,lease,task,text(row,"dispute_id"));done=rows.size()<30;}
            counts(company,channel,lease,taskId);require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_exchange_sync_item WHERE company_code=? AND task_id=? AND result='FAILED'",Long.class,company,taskId)==0,"部分申请同步失败，成功项保留；请查看逐单结果");
            renew(company,channel,lease);final long completedId=taskId;final boolean finished=done;tx().execute(s->{require(!repository.db().query("SELECT channel_id FROM oms_exchange_config WHERE company_code=? AND channel_id=? AND lease_token=? AND lease_until>NOW() FOR UPDATE",ROW,company,channel,lease).isEmpty(),"换货同步租约已失效");repository.db().update("UPDATE oms_exchange_sync SET state=?,page_no=page_no+1,attempts=0,next_attempt=NOW(),last_error='' WHERE company_code=? AND id=?",finished?"COMPLETED":"RUNNING",company,completedId);repository.db().update("UPDATE oms_exchange_config SET last_error='' WHERE company_code=? AND channel_id=?",company,channel);if(finished&&"AUTO".equals(text(task,"mode")))repository.db().update("UPDATE oms_exchange_config SET cursor_time=GREATEST(cursor_time,?),next_run=DATE_ADD(NOW(),INTERVAL 60 SECOND),last_error='' WHERE company_code=? AND channel_id=?",task.get("end_time"),company,channel);return null;});
        }catch(RuntimeException e){String message=e instanceof IllegalArgumentException?e.getMessage():"换货同步失败，请核对渠道授权或交互日志";if(message==null)message="换货同步失败";final String error=message.substring(0,Math.min(500,message.length()));final Long failed=taskId;tx().execute(t->{fence(company,channel,lease);if(failed!=null)repository.db().update("UPDATE oms_exchange_sync SET state=IF(attempts>=4,'FAILED','RETRY'),attempts=attempts+1,last_error=?,next_attempt=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND id=?",error,company,failed);repository.db().update("UPDATE oms_exchange_config SET last_error=?,next_run=DATE_ADD(NOW(),INTERVAL 60 SECOND) WHERE company_code=? AND channel_id=?",error,company,channel);return null;});
        }finally{repository.db().update("UPDATE oms_exchange_config SET lease_token=NULL,lease_until=NULL WHERE company_code=? AND channel_id=? AND lease_token=?",company,channel,lease);}}
    @PreDestroy public void close(){executor.close();}
}
